let argument raw index name default =
  let args = Json.array (field "args" raw) in
  if index < List.length args then List.nth args index
  else Option.value (List.assoc_opt name (Json.object_fields (field "kwargs" raw))) ~default
let alternative_make raw =
  let arg = argument raw in
  let strategy = Json.string (arg 0 "strategy" Json.Null) in
  let candidate = optional A.Candidate.of_json (arg 1 "candidate" Json.Null) in
  let constraint_violations = Json.array (arg 2 "constraint_violations" (Json.Array [])) |> List.map Json.string in
  let check = optional E.Check_result.of_json (arg 3 "check" Json.Null) in
  let generation_error = optional Json.string (arg 4 "generation_error" Json.Null) in
  S.Alternative.make ~strategy ?candidate ~constraint_violations ?check ?generation_error ()
let result_make raw =
  let arg = argument raw in
  let request_fingerprint = Json.string (arg 0 "request_fingerprint" Json.Null) in
  let history_fingerprint = Json.string (arg 1 "history_fingerprint" Json.Null) in
  let until = optional number (arg 2 "until" Json.Null) in
  let config = A.Config.of_json (arg 3 "config" Json.Null) in
  let minimize = Json.string (arg 4 "minimize" Json.Null) in
  let alternatives = Json.array (arg 5 "alternatives" Json.Null) |> List.map S.Alternative.of_json in
  S.Result.make ~request_fingerprint ~history_fingerprint ?until ~config ~minimize alternatives
let alternative_properties value = Json.Object [
  "fingerprint",str (S.Alternative.fingerprint value);
  "gate_count",option_json Json.int (S.Alternative.gate_count value);
  "status",str (S.Alternative.status value)]
let result_properties value = Json.Object [
  "fingerprint",str (S.Result.fingerprint value);
  "selected_strategy",option_json str (S.Result.selected_strategy value);
  "candidate",option_json A.Candidate.to_json (S.Result.candidate value);
  "outcome",str (S.Result.outcome value);
  "checked_candidates",Json.int (S.Result.checked_candidates value);
  "rejected_candidates",Json.int (S.Result.rejected_candidates value)]
let replay_domain fixture =
  let raw = field "raw" fixture and api = Json.string (field "api" fixture) in
  match api with
  | "SyntheticAlternative.__init__" ->
      let value = alternative_make raw in S.Alternative.to_json value,alternative_properties value
  | "SyntheticAlternative.from_dict" ->
      let value = S.Alternative.of_json (argument raw 0 "data" Json.Null) in
      S.Alternative.to_json value,alternative_properties value
  | "SyntheticSelectionResult.__init__" ->
      let value = result_make raw in S.Result.to_json value,result_properties value
  | "SyntheticSelectionResult.from_dict" ->
      let value = S.Result.of_json (argument raw 0 "data" Json.Null) in S.Result.to_json value,result_properties value
  | "SyntheticSelectionResult.from_json" ->
      let value = S.Result.of_json (Json.parse (Json.string (argument raw 0 "text" Json.Null))) in
      S.Result.to_json value,result_properties value
  | _ -> fail ("Uncovered original domain operation: "^api)
let check_domain raw =
  let fixture = Json.parse raw in
  let id = Json.string (field "id" fixture) in
  if field "outcome" fixture=str "returned" then (
    let actual,properties = replay_domain fixture in
    equal (id^": full domain record") (field "result" fixture) actual;
    equal (id^": all computed properties") (field "properties" fixture) properties
  ) else (
    let message = Json.string (field "message" (field "error" fixture)) in
    let expected_code = if message="Unsupported selection schema/policy." || message="Unsupported alternative schema."
      then "unsupported_schema" else "synthetic_selection" in
    match replay_domain fixture with
    | _ -> fail (id^": malformed domain accepted")
    | exception Diagnostic.Error error ->
        require (error.message=message && error.code=expected_code) (id^": exact rejection mismatch: "^error.message))
let inputs fixture =
  let input = field "input" fixture in
  let request = Realization_request.of_json (field "request" input) in
  let history = Json.array (field "history" input) |> List.map Execution_data.Input_frame.of_json in
  let until = optional number (field "until" input) in
  let config = optional A.Config.of_json (field "config" input) in
  request,history,until,config
let mutated_ids = [
  "tests/test_synthetic_selection.py::SyntheticSelectionTests.test_both_execution_failures_exhaust_only_the_declared_search/api/0";
  "tests/test_synthetic_selection.py::SyntheticSelectionTests.test_independent_checker_rejects_faulty_demorgan_rewrite_before_ranking/api/0"]
let select_fixture fixture =
  let request,history,until,config = inputs fixture in
  if field "mutated_producer" fixture=Json.Bool false then P.select ?until ?config request history
  else (
    let id = Json.string (field "id" fixture) in
    require (List.mem id mutated_ids) ("Unpinned producer mutation: "^id);
    let proposals = Json.array (field "proposals" fixture) in
    let calls = ref [] in
    let module Injected = P.Make (struct
      let propose ~config ~limits:_ ~parent request =
        W.charge parent 1;
        let strategy = A.Config.conjunction_strategy config in
        calls := strategy :: !calls;
        let document = List.find (fun item -> field "strategy" item=str strategy) proposals in
        let candidate = A.Candidate.of_json (field "candidate" document) in
        require (A.Candidate.request_fingerprint candidate=Realization_request.fingerprint request)
          "Injected proposal request identity changed";
        require (A.Config.fingerprint (A.Candidate.generator_config candidate)=A.Config.fingerprint config)
          "Injected proposal configuration changed";
        candidate
    end) in
    let result = Injected.select ?until ?config request history in
    require (List.rev !calls=S.strategies) "Every retained mutated proposal must run exactly once";
    result)
let check_selector raw =
  let fixture = Json.parse raw in
  let id = Json.string (field "id" fixture) in
  if field "outcome" fixture=str "returned" then (
    let result = select_fixture fixture in
    equal (id^": complete freshly selected result") (field "result" fixture) (S.Result.to_json result);
    require (str (S.Result.fingerprint result)=field "fingerprint" fixture) (id^": exact result identity")
  ) else (
    match select_fixture fixture with
    | _ -> fail (id^": unsupported selection accepted")
    | exception G.Unsupported error ->
        require (G.format_error error=Json.string (field "message" (field "error" fixture))) (id^": policy rejection precedence"))
let resource_failure label operation =
  match operation () with
  | _ -> fail (label^": resource reduction accepted")
  | exception Diagnostic.Error error ->
      require (List.mem error.code ["realization_work_limit";"realization_monitor_limit";
        "realization_input_limit";"realization_report_limit";"parent_selection_limit"])
        (label^": incorrect diagnostic "^error.code)
let resource_tests () =
  let fixture = List.find (fun raw ->
    let id = Json.string (field "id" (Json.parse raw)) in
    String.equal id "tests/test_synthetic_selection.py::SyntheticSelectionTests.test_hard_gate_bound_cannot_be_overridden_by_preference/api/0") selector_literals
    |> Json.parse in
  let request,history,until,config = inputs fixture in
  let baseline,usage = P.select_with_usage ?until ?config request history in
  require (S.Result.outcome baseline="exhausted") "Resource fixture must avoid execution failure recovery";
  (* Observe actual child options while still running both real proposals.
     Original Python's first complete alternative contains 350 values and
     244 object keys: the second child must lose all 594 publication nodes. *)
  let supplied_limits = ref [] in
  let module Recorded = P.Make (struct
    let propose ~config ~limits ~parent request =
      supplied_limits := (A.Config.conjunction_strategy config,G.limits_json limits) :: !supplied_limits;
      G.propose ~config ~limits ~parent request
  end) in
  let recorded = Recorded.select ?until ?config request history in
  equal "Recording child limits changed the complete selection" (field "result" fixture) (S.Result.to_json recorded);
  let first_raw = S.Alternative.to_json (List.hd (S.Result.alternatives recorded)) in
  let rec object_keys = function
    | Json.Object fields -> List.fold_left (fun total (_,value) -> total+1+object_keys value) 0 fields
    | Json.Array values -> List.fold_left (fun total value -> total+object_keys value) 0 values
    | _ -> 0 in
  let value_nodes = (Legacy_ascii.measure first_raw).nodes and key_nodes = object_keys first_raw in
  require (value_nodes=350 && key_nodes=244) "Independent first-alternative node census changed";
  let report_nodes limits = Json.integer (field "max_report_nodes" (field "shared" limits)) |> Z.to_int in
  let maximum = report_nodes (G.limits_json G.default_limits) in
  let received = List.rev !supplied_limits |> List.map (fun (strategy,limits) -> strategy,report_nodes limits) in
  require (received=["native",maximum;"de_morgan",maximum-value_nodes-key_nodes])
    "Second real proposal reused publication capacity already consumed by object keys";
  let exact = P.make_limits ~max_work:usage.work_charged () in
  let again,exact_usage = P.select_with_usage ?until ?config ~limits:exact request history in
  equal "Exact shared selection work succeeds" (S.Result.to_json baseline) (S.Result.to_json again);
  require (usage.work_charged=exact_usage.work_charged) "Selection charge must be deterministic";
  resource_failure "One-under shared work" (fun () -> P.select ?until ?config
    ~limits:(P.make_limits ~max_work:(usage.work_charged-1) ()) request history);
  let parent amount = W.create ~profile:"selection-test" ~error_code:"parent_selection_limit" ~maximum:amount () in
  let exact_parent = parent usage.work_charged in
  ignore (P.select ?until ?config ~parent:exact_parent request history);
  require (W.remaining exact_parent=0) "Every child and publication charges shared parent";
  resource_failure "One-under outer parent" (fun () -> P.select ?until ?config
    ~parent:(parent (usage.work_charged-1)) request history);
  List.iter (fun (label,limits) -> resource_failure label (fun () -> P.select ?until ?config ~limits request history))
    ["Work",P.make_limits ~max_work:1 ();"Retention",P.make_limits ~max_monitor_items:1 ();
     "Input",P.make_limits ~max_request_bytes:1 ();"Output bytes",P.make_limits ~max_report_bytes:1 ();
     "Output nodes",P.make_limits ~max_report_nodes:1 ()];
  resource_failure "Whole result publication bytes" (fun () -> P.select ?until ?config
    ~limits:(P.make_limits ~max_report_bytes:(S.Result.canonical_size baseline-1) ()) request history);
  (match S.Result.make ~request_fingerprint:(S.Result.request_fingerprint baseline)
      ~history_fingerprint:(S.Result.history_fingerprint baseline) ?until
      ~config:(S.Result.config baseline) ~minimize:"none" [] with
   | _ -> fail "Empty alternatives accepted"
   | exception Diagnostic.Error error -> require (error.code="synthetic_selection") "Empty bounded inventory error");
  let rec cyclic = fixture :: cyclic in
  (* A raw cyclic JSON list is rejected by preflight before field decoding. *)
  (match S.Result.of_json (Json.Array cyclic) with
   | _ -> fail "Cyclic raw selection accepted"
   | exception Diagnostic.Error error -> require (List.mem error.code ["synthetic_selection_limit";"synthetic_selection_cycle"])
       "Cyclic selection must terminate at its resource boundary");
  let invalids = [Runtime_number.Real nan;Runtime_number.Real infinity;Runtime_number.Integer (Z.shift_left Z.one 2048)] in
  List.iter (fun until -> match S.Result.make ~request_fingerprint:(S.Result.request_fingerprint baseline)
      ~history_fingerprint:(S.Result.history_fingerprint baseline) ~until ~config:(S.Result.config baseline)
      ~minimize:"none" (S.Result.alternatives baseline) with
    | _ -> fail "Invalid native horizon accepted"
    | exception Diagnostic.Error error -> require (error.code="synthetic_selection" && error.message="Invalid selection horizon.")
        "Native constructor horizon has original diagnostic") invalids;
  let fresh = P.select ?until ?config request history in
  equal "Failed sessions cannot contaminate fresh selection" (S.Result.to_json baseline) (S.Result.to_json fresh)
let () =
  require (List.length domain_literals=99 && List.length selector_literals=24) "Independent selection inventory changed";
  List.iter check_domain domain_literals;
  List.iter check_selector selector_literals;
  resource_tests ();
  print_endline "synthetic selection: complete original records, constructors, mutations, fresh checks and aggregate budgets passed"
